<!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><title>تحویل</title><style>body{font-family:Tahoma;background:#07111f;color:#e9f3fb;padding:30px}table{width:100%;background:#0a1b2b;border-collapse:collapse}td,th{padding:12px;border-bottom:1px solid #20384d}button,input{padding:8px;border-radius:7px;border:1px solid #29465e;background:#10283c;color:#fff}button{background:#1c806e}</style></head><body><h1>درخواست‌های تحویل</h1><table><tr><th>سفارش</th><th>مشتری</th><th>زمان</th><th>وضعیت</th><th>عملیات</th></tr>@foreach($deliveries as $d)<tr><td>{{ $d->order_number }}</td><td>{{ $d->customer_name }}</td><td>{{ $d->scheduled_at }}</td><td>{{ $d->status }}</td><td>@if($d->status==='pending')<button onclick="issue({{ $d->id }})">خروج انبار</button>@elseif($d->status==='issued')<button onclick="handover({{ $d->id }})">تحویل به مشتری</button>@endif</td></tr>@endforeach</table><script>const token='{{ csrf_token() }}';async function post(url,data={}){const r=await fetch(url,{method:'POST',headers:{'Accept':'application/json','Content-Type':'application/json','X-CSRF-TOKEN':token},body:JSON.stringify(data)});const j=await r.json();if(!r.ok)throw Error(j.message||'خطا');return j}async function issue(id){try{await post('/api/delivery-requests/'+id+'/issue');location.reload()}catch(e){alert(e.message)}}async function handover(id){const received=prompt('نام تحویل‌گیرنده را وارد کنید');if(!received)return;try{await post('/api/delivery-requests/'+id+'/handover',{received_by:received});location.reload()}catch(e){alert(e.message)}}</script></body></html>